import React, { useState, useMemo, useEffect, useRef, Fragment } from "react";

const STORAGE_KEY = "campaign-tracker-v3";
const ZEUS_KEY = "campaign-tracker-zeus";
const EXPORT_KEY = "campaign-tracker-last-export";
const REMINDERS_KEY = "campaign-tracker-reminders";
const ACTIVITY_KEY = "campaign-tracker-activity";
const ARCHIVE_KEY = "campaign-tracker-archive";
const CSV_MAPPINGS_KEY = "campaign-tracker-csv-mappings";
// Which Quick Check-in FILE SOURCE a tracker platform's delivery comes from — used to seed check-in
// name-memory (so e.g. a mid-flight tactic switch's campaigns are REMEMBERED on the next drop, not
// re-matched by a weak fuzzy score). Mirrors SOURCE_PLATFORMS (the inverse map) in QuickCheckInPanel.
function platformToFileSource(platform){
  if(["FB","FBV","IG"].includes(platform)) return "Facebook/Meta";
  if(platform==="SP") return "Snapchat";
  if(["TD","TDV","TDA","CTV","OTT","OTTD"].includes(platform)) return "TradeDesk";
  if(platform==="DSP") return "DSP";
  if(["SEM","YT"].includes(platform)) return "Google";
  if(["GCTV","PCTV","AECTV"].includes(platform)) return "Madhive";
  return null;
}
// Write check-in name-memory entries directly (App-side), so a flow OUTSIDE the QCI panel (like the
// switch-tactic helper) can pre-teach the mapping. The QCI reads this key fresh each time it opens.
function seedCheckinMemory(seeds){ // seeds: [{name, campId, platform}]
  try{
    const maps = JSON.parse(localStorage.getItem(CSV_MAPPINGS_KEY)||"{}");
    let wrote=0;
    seeds.forEach(({name, campId, platform})=>{
      const src = platformToFileSource(platform);
      const nm = String(name||"").trim();
      if(!src || !nm || !campId) return;
      maps[`${src}||${nm.toLowerCase()}`] = { campId:String(campId), campName:nm, source:src, learnedAt:(typeof getToday==="function"?getToday():"") };
      wrote++;
    });
    if(wrote) localStorage.setItem(CSV_MAPPINGS_KEY, JSON.stringify(maps));
    return wrote;
  }catch(e){ return 0; }
}
const USER_INITIALS_KEY = "campaign-tracker-user-initials";
const VAULT_KEY = "campaign-tracker-report-vault"; // [{id, savedAt, client, title, dateRange, brandColor, totals, campaigns, notes}]
const MONTH_LOCK_KEY = "campaign-tracker-month-locks"; // {"2026-05":{lockedAt,label,totalRevenue,totalSpend,totalProfit,margin,campaigns:[]}}
const MONTH_RESET_KEY = "campaign-tracker-last-month-reset"; // "YYYY-MM" of the last new-month metrics reset handled
const MONTHLY_BACKUP_KEY = "campaign-tracker-monthly-backups"; // {"YYYY-MM":{savedAt, campaigns:[...closing snapshot]}}
const BACKUP_CFG_KEY = "campaign-tracker-backup-cfg"; // {enabled, lastBackupDate:"YYYY-MM-DD", lastBackupAt, folderName, method}
const ARCHIVE_DAYS = 5;

// ── Auto-backup file plumbing (File System Access API + Downloads fallback) ────────────────
// The File System Access API (Chrome/Edge, secure context incl. localhost) lets the user grant
// write access to ONE folder — Desktop, a backups folder, or a Google-Drive-for-Desktop folder
// (which then syncs the file to the cloud). The granted directory handle isn't JSON-serializable,
// so it's stashed in IndexedDB and re-permission-checked. If the folder isn't writable silently
// (permission lapses after a browser restart) we fall back to a normal download so a backup still
// happens on user-initiated runs. Silent guarantee only holds while folder permission is "granted".
const FSA_SUPPORTED = typeof window !== "undefined" && "showDirectoryPicker" in window;
function _backupIdb(){
  return new Promise((res,rej)=>{
    const r = indexedDB.open("zeus-backup", 2);
    r.onupgradeneeded = () => { try { const db=r.result;
      if(!db.objectStoreNames.contains("handles"))   db.createObjectStore("handles");
      if(!db.objectStoreNames.contains("snapshots"))  db.createObjectStore("snapshots"); // full-payload safety copies
    } catch(e){} };
    r.onsuccess = () => res(r.result);
    r.onerror = () => rej(r.error);
  });
}
// A durable, OUT-OF-localStorage copy of the whole tracker. IndexedDB is a separate store that survives a
// localStorage wipe (it survived Austin's 2026-07-29 power-loss wipe — the folder handle lived here), so
// this is the copy that makes data loss recoverable even with NO file backup. Keeps "latest" + dated ones.
async function idbSaveSnapshot(jsonStr){
  try{
    const db=await _backupIdb();
    const date=new Date().toISOString().slice(0,10), rec={ at:Date.now(), date, json:jsonStr };
    await new Promise((res,rej)=>{ const tx=db.transaction("snapshots","readwrite"); const st=tx.objectStore("snapshots");
      st.put(rec,"latest"); st.put(rec,"day:"+date); tx.oncomplete=res; tx.onerror=()=>rej(tx.error); });
    try{ await new Promise((res)=>{ const tx=db.transaction("snapshots","readwrite"); const st=tx.objectStore("snapshots");
      const rq=st.getAllKeys(); rq.onsuccess=()=>{ const cut=new Date(Date.now()-21*86400000).toISOString().slice(0,10);
        (rq.result||[]).forEach(k=>{ if(typeof k==="string" && k.startsWith("day:") && k.slice(4)<cut) st.delete(k); }); res(); }; rq.onerror=()=>res(); }); }catch(e){}
    db.close(); return true;
  }catch(e){ return false; }
}
async function idbGetSnapshot(){
  try{ const db=await _backupIdb(); const v=await new Promise((res,rej)=>{ const tx=db.transaction("snapshots","readonly");
    const rq=tx.objectStore("snapshots").get("latest"); rq.onsuccess=()=>res(rq.result||null); rq.onerror=()=>rej(rq.error); }); db.close(); return v; }catch(e){ return null; }
}
// Pre-import stash → makes an Import UNDOABLE (a wrong/older file over newer data is the classic footgun).
async function idbSavePreimport(jsonStr){ try{ const db=await _backupIdb(); await new Promise((res,rej)=>{ const tx=db.transaction("snapshots","readwrite"); tx.objectStore("snapshots").put({ at:Date.now(), json:jsonStr },"preimport"); tx.oncomplete=res; tx.onerror=()=>rej(tx.error); }); db.close(); return true; }catch(e){ return false; } }
async function idbGetPreimport(){ try{ const db=await _backupIdb(); const v=await new Promise((res,rej)=>{ const tx=db.transaction("snapshots","readonly"); const rq=tx.objectStore("snapshots").get("preimport"); rq.onsuccess=()=>res(rq.result||null); rq.onerror=()=>rej(rq.error); }); db.close(); return v; }catch(e){ return null; } }
async function idbClearPreimport(){ try{ const db=await _backupIdb(); await new Promise((res)=>{ const tx=db.transaction("snapshots","readwrite"); tx.objectStore("snapshots").delete("preimport"); tx.oncomplete=res; tx.onerror=res; }); db.close(); }catch(e){} }
async function idbSetDirHandle(h){ try{ const db=await _backupIdb(); await new Promise((res,rej)=>{ const tx=db.transaction("handles","readwrite"); tx.objectStore("handles").put(h,"dir"); tx.oncomplete=res; tx.onerror=()=>rej(tx.error); }); db.close(); }catch(e){ console.error("backup idb set",e); } }
async function idbGetDirHandle(){ try{ const db=await _backupIdb(); const h=await new Promise((res,rej)=>{ const tx=db.transaction("handles","readonly"); const rq=tx.objectStore("handles").get("dir"); rq.onsuccess=()=>res(rq.result||null); rq.onerror=()=>rej(rq.error); }); db.close(); return h; }catch(e){ return null; } }
async function idbClearDirHandle(){ try{ const db=await _backupIdb(); await new Promise((res)=>{ const tx=db.transaction("handles","readwrite"); tx.objectStore("handles").delete("dir"); tx.oncomplete=res; tx.onerror=res; }); db.close(); }catch(e){} }
// Write JSON into the folder, then prune: keep the newest `keepDaily` dated files + any month-start
// (…-01) file as a monthly snapshot, so the folder stays a tidy rolling safety net.
async function writeBackupToFolder(dirHandle, filename, jsonStr, keepDaily=14){
  const fh = await dirHandle.getFileHandle(filename, {create:true});
  const w = await fh.createWritable();
  await w.write(jsonStr);
  await w.close();
  try {
    const re = /^campaign-tracker-(\d{4})-(\d{2})-(\d{2})\.json$/;
    const ours = [];
    for await (const [name, handle] of dirHandle.entries()){
      const m = name.match(re);
      if (m && handle.kind === "file") ours.push({ name, key:`${m[1]}-${m[2]}-${m[3]}`, day:m[3] });
    }
    ours.sort((a,b)=> a.key<b.key?1 : a.key>b.key?-1 : 0); // newest first
    let kept = 0;
    for (const f of ours){
      if (f.day === "01") continue;                 // keep month-start snapshots as monthly history
      kept++;
      if (kept > keepDaily){ try { await dirHandle.removeEntry(f.name); } catch(e){} }
    }
  } catch(e){ /* rotation is best-effort — never block the actual save */ }
  return true;
}
function downloadBackupFile(filename, jsonStr){
  const b = new Blob([jsonStr], {type:"application/json"});
  const url = URL.createObjectURL(b); const a = document.createElement("a");
  a.href = url; a.download = filename; document.body.appendChild(a); a.click(); document.body.removeChild(a); URL.revokeObjectURL(url);
}
const MAX_LOG_ENTRIES = 250; // was 500 — halved to save localStorage (Austin, 2026-07-17)
// DSP campaigns rarely report real media spend, so we MODEL their cost at a flat assumed CPM. This
// lets the Revenue tab surface projected revenue/profit for DSP (esp. the "if you hit goal" forecast)
// before any real impressions/spend exist. Easy to change here; could move to Config for per-user later.
const DSP_EST_CPM = 2.75;
// Show the platform sync status badges (Meta / TTD / DSP / Google / Snap) in the top header.
// Off for now since no platforms are connected — flip to true once you start syncing a platform.
const SHOW_SYNC_BADGES = false;

// ── Storage usage helpers ────────────────────────────────────────────────────
// Browsers cap localStorage at roughly 5 MB per site. We surface usage in Config and warn
// loudly if a save ever fails (instead of failing silently), so a full store can't quietly
// lose a check-in.
const STORAGE_LIMIT_BYTES = 5 * 1024 * 1024; // ~5 MB typical per-origin cap
function getStorageBytes() {
  let total = 0;
  try { for (let i = 0; i < localStorage.length; i++) { const k = localStorage.key(i); const v = localStorage.getItem(k) || ""; total += (k.length + v.length) * 2; } } catch {}
  return total; // UTF-16 → 2 bytes/char
}
function fmtBytes(b) { return b >= 1048576 ? (b / 1048576).toFixed(1) + " MB" : Math.round(b / 1024) + " KB"; }

// Per-campaign fields that hold DELIVERY DETAIL rather than the campaign itself. These are what
// actually grow without bound: a snapshot carries `breakdown`/`priorBreakdown` (one row per ad line,
// per drop), creativeReport carries one row per AD, and metricSeries carries a reading per day.
// The campaign's own identity/goal/revenue fields are a few hundred bytes and never move the needle.
const HEAVY_FIELDS = ["metricSeries","checkInLog","metaSnapshots","ttdSnapshots","dspSnapshots",
                      "googleSnapshots","snapSnapshots","creativeReport","history"];
// Size of one value as stored (UTF-16 → 2 bytes/char). Mirrors getStorageBytes' accounting so the
// breakdown and the total agree.
function _jsonBytes(v) { try { return v === undefined ? 0 : JSON.stringify(v).length * 2; } catch { return 0; } }

// Undo snapshot for an EDIT (field changes, check-ins, bulk edits). Undo MERGES this over the live
// campaign, so any field the edit can't touch doesn't need to be in here — the live copy still has
// it. Dropping them matters a lot: these are the fattest fields on a campaign and the log holds up
// to MAX_LOG_ENTRIES (500) of these, so one clone each is 500 clones on disk.
function leanUndoSnapshot(c) {
  const { metricSeries, metaSnapshots, ttdSnapshots, dspSnapshots, googleSnapshots, snapSnapshots,
          checkInLog, creativeReport, ...rest } = c;
  return rest;
}
// Undo snapshot for the "clear metrics / new month reset" path, which DOES wipe checkInLog and the
// five snapshot objects — so those must be kept to undo faithfully. It never touches metricSeries or
// creativeReport though, so cloning THOSE was pure waste: the live campaign keeps them either way.
// (metricSeries is the single largest field on a campaign — a reading per day, per campaign.)
function clearMetricsUndoSnapshot(c) {
  const { metricSeries, creativeReport, ...rest } = c;
  return rest;
}

// How far back the archive is kept before a cleanup offers to drop it. Austin: "I only need to
// archive for 12 months or so."
const ARCHIVE_RETENTION_MONTHS = 12;

// Strips the DELIVERY DETAIL from an archived campaign. Deliberately keeps the campaign's own
// scalars (impressions/spend/ctr/cpm…): they're a few bytes each, they're what the Archive tab
// shows, and monthly revenue can still read them — so dropping them would risk money to save
// nothing. What goes is the per-day / per-line / per-ad detail, which is ~95% of the weight and
// is only ever used to draw pacing charts for a LIVE campaign.
// Note this keeps id + campaignName + platform, so archived campaigns stay mappable in Quick
// Check-in (see the full-archive mapping in the QCI panel).
function slimArchivedCampaign(c) {
  const { metricSeries, checkInLog, metaSnapshots, ttdSnapshots, dspSnapshots,
          googleSnapshots, snapSnapshots, creativeReport, ...rest } = c;
  return rest;
}

// REVENUE SAFETY: a campaign that ran recently keeps ALL its data — never slimmed, never dropped —
// because closedMonthMetrics falls back to a campaign's `metricSeries` to reconstruct a month's
// delivery when that month has no backup/lock yet (i.e. an unclosed recent month). Austin: "make sure
// this doesn't affect the campaigns that ran in the past month or so because this will affect revenue."
// So we protect anything whose flight ended (or, if undated, was archived) within this window. Undated
// entries are protected too — we can't prove they're old.
const REVENUE_SAFE_MONTHS = 3;
function archivedRanRecently(c, monthsBack = REVENUE_SAFE_MONTHS) {
  const iso = (x) => (x && /^\d{4}-\d{2}-\d{2}$/.test(x)) ? x : null;
  const ref = iso(c && c.endDate) || iso(c && c.archivedDate);
  if (!ref) return true; // undatable → protect (can't prove it ran long ago)
  const n = new Date();
  const cut = new Date(n.getFullYear(), n.getMonth() - monthsBack, 1);
  const p = (x) => String(x).padStart(2, "0");
  return ref >= `${cut.getFullYear()}-${p(cut.getMonth()+1)}-01`;
}

// Works out what a cleanup WOULD do, without doing it — so the confirm can state real numbers.
// `drop` = archived longer ago than the retention window; `slimmed` = everything kept, minus its
// delivery detail — EXCEPT recently-run campaigns, which are left fully intact (see archivedRanRecently).
// Entries with no archivedDate are never dropped (we can't age what we can't date).
function planArchiveCleanup(archive, retentionMonths = ARCHIVE_RETENTION_MONTHS) {
  const list = Array.isArray(archive) ? archive : [];
  const n = new Date();
  const cut = new Date(n.getFullYear(), n.getMonth() - retentionMonths, n.getDate());
  const p = (x) => String(x).padStart(2, "0");
  const cutIso = `${cut.getFullYear()}-${p(cut.getMonth()+1)}-${p(cut.getDate())}`;
  const drop = [], keep = [];
  list.forEach(a => {
    const d = a && a.archivedDate;
    // Recently-run campaigns are NEVER dropped, even if their archivedDate is somehow old.
    if (d && /^\d{4}-\d{2}-\d{2}$/.test(d) && d < cutIso && !archivedRanRecently(a)) drop.push(a); else keep.push(a);
  });
  // Slim only the non-recent kept entries; recent ones pass through untouched (revenue safety).
  let protectedRecent = 0;
  const slimmed = keep.map(a => { if (archivedRanRecently(a)) { protectedRecent++; return a; } return slimArchivedCampaign(a); });
  const before = _jsonBytes(list), after = _jsonBytes(slimmed);
  // How many kept, NON-recent entries actually carry detail worth stripping (for an honest "nothing to do").
  const withDetail = keep.filter(a => !archivedRanRecently(a) && HEAVY_FIELDS.some(f => f !== "history" && a && a[f] !== undefined)).length;
  return { cutIso, drop, keep, slimmed, before, after, protectedRecent,
           freed: Math.max(0, before - after), withDetail, safeMonths: REVENUE_SAFE_MONTHS };
}

// Answers "what is actually using my 5 MB?" — every localStorage key by size, plus a field-level
// breakdown INSIDE the campaign/archive blobs (the two that dominate). Read-only; changes nothing.
function getStorageBreakdown() {
  const keys = [];
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i); const v = localStorage.getItem(k) || "";
      keys.push({ key: k, bytes: (k.length + v.length) * 2 });
    }
  } catch {}
  keys.sort((a, b) => b.bytes - a.bytes);

  // Field-level totals across campaigns + archive.
  const fields = {}; let campCount = 0, archCount = 0, coreBytes = 0;
  const scan = (raw, isArch) => {
    let list = null; try { list = JSON.parse(raw || "null"); } catch {}
    if (!Array.isArray(list)) return;
    if (isArch) archCount = list.length; else campCount = list.length;
    list.forEach(c => {
      if (!c || typeof c !== "object") return;
      let heavy = 0;
      HEAVY_FIELDS.forEach(f => {
        if (c[f] === undefined) return;
        const b = _jsonBytes(c[f]); heavy += b;
        const slot = fields[f] || (fields[f] = { bytes: 0, active: 0, archived: 0 });
        slot.bytes += b; if (isArch) slot.archived += b; else slot.active += b;
      });
      coreBytes += Math.max(0, _jsonBytes(c) - heavy); // the campaign minus its delivery detail
    });
  };
  try { scan(localStorage.getItem("campaign-tracker-v3"), false); } catch {}
  try { scan(localStorage.getItem("campaign-tracker-archive"), true); } catch {}

  const fieldList = Object.entries(fields).map(([name, v]) => ({ name, ...v }))
    .filter(f => f.bytes > 0).sort((a, b) => b.bytes - a.bytes);
  return { keys, fieldList, coreBytes, campCount, archCount,
           total: keys.reduce((s, k) => s + k.bytes, 0) };
}

