    const tagged = ms.map((e,idx)=>{ const d=parseSeriesDate(e?.d); return { idx, mk: d?`${d.getFullYear()}-${d.getMonth()}`:null, t: d?d.getTime():0, i: parseInt(e?.i)||0 }; });
